import {particleLessons,allParticleQuestions} from './data.js';

// Reviewed vocabulary groups and compatible slots. Stable IDs are part of backup history.
// Questions are assembled only when selected; no network service is used.
const word=(id,jp,zh)=>({id,jp,zh});
const people=[word('self','{私|わたし}','我'),word('tanaka','{田中|たなか}さん','田中'),word('hayashi','{林|りん}さん','林'),word('sato','{佐藤|さとう}さん','佐藤')];
const roles=[word('student','{学生|がくせい}','學生'),word('teacher','{先生|せんせい}','老師'),word('employee','{会社員|かいしゃいん}','公司職員'),word('doctor','{医者|いしゃ}','醫生'),word('nurse','{看護師|かんごし}','護理師'),word('clerk','{店員|てんいん}','店員')];
const pointers=[word('this','これ','這個'),word('that','それ','那個'),word('overthere','あれ','那邊那個')];
const things=[word('book','{本|ほん}','書'),word('notebook','ノート','筆記本'),word('umbrella','{傘|かさ}','雨傘'),word('key','かぎ','鑰匙'),word('bag','かばん','包包'),word('pen','ペン','筆')];
const groups=[
  {id:'drink',verb:word('drink','{飲|の}みます','喝'),
   places:[word('cafe','カフェ','咖啡店'),word('home','うち','家裡'),word('office','{会社|かいしゃ}','公司')],
   objects:[word('water','{水|みず}','水'),word('tea','お{茶|ちゃ}','茶'),word('coffee','コーヒー','咖啡'),word('milk','{牛乳|ぎゅうにゅう}','牛奶'),word('juice','ジュース','果汁'),word('blacktea','{紅茶|こうちゃ}','紅茶')]},
  {id:'eat',verb:word('eat','{食|た}べます','吃'),
   places:[word('home','うち','家裡'),word('canteen','{食堂|しょくどう}','餐廳'),word('park','{公園|こうえん}','公園')],
   objects:[word('apple','りんご','蘋果'),word('bread','パン','麵包'),word('sandwich','サンドイッチ','三明治'),word('riceball','おにぎり','飯糰'),word('bento','お{弁当|べんとう}','便當'),word('banana','バナナ','香蕉')]},
  {id:'read',verb:word('read','{読|よ}みます','讀'),
   places:[word('library','{図書館|としょかん}','圖書館'),word('home','うち','家裡'),word('cafe','カフェ','咖啡店')],
   objects:[word('book','{本|ほん}','書'),word('newspaper','{新聞|しんぶん}','報紙'),word('magazine','{雑誌|ざっし}','雜誌'),word('comic','{漫画|まんが}','漫畫'),word('novel','{小説|しょうせつ}','小說'),word('letter','{手紙|てがみ}','信')]}
];
// Each pair is approved separately; e.g. a language teacher is not generated by mixing arbitrary nouns.
const categories=[
  [word('japanese','{日本語|にほんご}','日文'),word('teacher','{先生|せんせい}','老師'),'日文老師'],
  [word('english','{英語|えいご}','英文'),word('teacher','{先生|せんせい}','老師'),'英文老師'],
  [word('music','{音楽|おんがく}','音樂'),word('teacher','{先生|せんせい}','老師'),'音樂老師'],
  [word('japanese','{日本語|にほんご}','日文'),word('book','{本|ほん}','書'),'日文的書'],
  [word('english','{英語|えいご}','英文'),word('book','{本|ほん}','書'),'英文的書'],
  [word('history','{歴史|れきし}','歷史'),word('book','{本|ほん}','書'),'歷史方面的書'],
  [word('japan','{日本|にほん}','日本'),word('company','{会社|かいしゃ}','公司'),'日本的公司'],
  [word('taiwan','{台湾|たいわん}','台灣'),word('company','{会社|かいしゃ}','公司'),'台灣的公司'],
  [word('school','{学校|がっこう}','學校'),word('teacher','{先生|せんせい}','老師'),'學校的老師'],
  [word('university','{大学|だいがく}','大學'),word('teacher','{先生|せんせい}','老師'),'大學的老師'],
  [word('math','{数学|すうがく}','數學'),word('teacher','{先生|せんせい}','老師'),'數學老師'],
  [word('science','{科学|かがく}','科學'),word('book','{本|ほん}','書'),'科學方面的書'],
  [word('cooking','{料理|りょうり}','料理'),word('book','{本|ほん}','書'),'料理方面的書'],
  [word('travel','{旅行|りょこう}','旅行'),word('book','{本|ほん}','書'),'旅行方面的書'],
  [word('china','{中国|ちゅうごく}','中國'),word('company','{会社|かいしゃ}','公司'),'中國的公司'],
  [word('taiwan','{台湾|たいわん}','台灣'),word('tea','お{茶|ちゃ}','茶'),'台灣的茶']
];
const places=[word('school','{学校|がっこう}','學校'),word('library','{図書館|としょかん}','圖書館'),word('park','{公園|こうえん}','公園'),word('station','{駅|えき}','車站'),word('classroom','{教室|きょうしつ}','教室')];
const spots=[word('desk','{机|つくえ}の{上|うえ}','桌上'),word('bag','かばんの{中|なか}','包包裡'),word('room','{部屋|へや}','房間裡'),word('classroom','{教室|きょうしつ}','教室裡')];
const smallThings=[things[0],things[1],things[3],things[5]];
const destinations=[...places.slice(0,4),word('supermarket','スーパー','超市'),word('hospital','{病院|びょういん}','醫院')];
const travelVerbs=[word('go','{行|い}きます','去'),word('come','{来|き}ます','來')];
const plain=s=>s.replace(/\{([^|{}]+)\|[^{}]+\}/g,'$1');
const signature=q=>plain(q.sentence);
const optionRules={
  topic:{options:['は','を','の'],answers:['は'],wrong:{を:'本句是在介紹話題，不是標記動作對象。',の:'「の」會把兩個名詞連成片語；本題要用主題句型說明前面的對象。'}},
  object:{options:['を','で','に'],answers:['を'],wrong:{で:'空格前面是被吃、喝或讀的東西，不是動作發生的場所。',に:'這裡要標示動作作用的對象，不是存在位置或移動目的地。'}},
  possession:{options:['の','は','を'],answers:['の'],wrong:{は:'「は」會把前面的人提出來當話題；本題要先組成「某人的物品」這個名詞片語。',を:'這裡沒有作用於物品的動作，要表達的是所屬關係。'}},
  category:{options:['の','に','で'],answers:['の'],wrong:{に:'本題要用前面的名詞修飾後面的名詞，不是位置或移動句。',で:'這裡不是動作場所，要把兩個名詞連起來說明類別。'}},
  addition:{options:['も','は','の'],answers:['も'],wrong:{は:'使用「は」可以單獨介紹，但沒有明確說出情境要求的「也」。',の:'「の」會連成名詞片語，無法表達本題的「也有相同情況」。'}},
  existence:{options:['に','で','を'],answers:['に'],wrong:{で:'本句的「います／あります」描述人或物存在的位置，不是在某處進行活動。',を:'空格前面是存在的位置，不是動作對象。'}},
  action:{options:['で','に','へ'],answers:['で'],wrong:{に:'這裡說的是在某處吃、喝或讀，不是用「います／あります」表示存在的位置。',へ:'「へ」可表示移動方向；本句是在這個地方做事情。'}},
  movement:{options:['に','へ','で'],answers:['に','へ'],wrong:{で:'空格前面是要去、來或回到的地方，不是動作發生的場所。'}}
};
function buildQuestion(descriptor){
  const {id,lesson,use,slots:s}=descriptor;
  let context,sentence,translation,why,words;
  const [a,b,c]=s;
  switch(descriptor.family){
    case 'identity':
      context=`用本課的主題句型介紹身分：${a.zh}是${b.zh}。`;
      sentence=`${a.jp}＿${b.jp}です。`;translation=`${a.zh}是${b.zh}。`;
      why=`「${plain(a.jp)}」是談論的主題，「${plain(b.jp)}です」說明身分。`;words=[a,b];break;
    case 'identify':
      context=`指著物品，用主題句型說「${a.zh}是${b.zh}」。`;
      sentence=`${a.jp}＿${b.jp}です。`;translation=`${a.zh}是${b.zh}。`;
      why=`「${plain(a.jp)}」提出眼前的東西，後面說明它是「${plain(b.jp)}」。`;words=[a,b];break;
    case 'object':case 'action':{
      const verb=descriptor.verb;
      context=use==='object'?`要說「在${a.zh}${verb.zh}${b.zh}」，空格在${b.zh}後面，請標示動作對象。`:`要說「在${a.zh}${verb.zh}${b.zh}」，請標示動作發生的場所。`;
      sentence=use==='object'?`${a.jp}で${b.jp}＿${verb.jp}。`:`${a.jp}＿${b.jp}を${verb.jp}。`;
      translation=`在${a.zh}${verb.zh}${b.zh}。`;
      why=use==='object'?`「${plain(b.jp)}」是「${plain(verb.jp)}」的對象，用「を」；「${plain(a.jp)}で」已經指出場所。`:`「${plain(verb.jp)}」是動作，「${plain(a.jp)}」是做這件事的場所，所以用「で」。`;
      words=[a,b,verb];break;
    }
    case 'owner':
      context=`說明這個物品屬於誰。請表達「是${a.zh}的${b.zh}」。`;
      sentence=`${a.jp}＿${b.jp}です。`;translation=`是${a.zh}的${b.zh}。`;
      why=`「${plain(a.jp)}の」修飾「${plain(b.jp)}」，說明物品的所屬。`;words=[a,b];break;
    case 'category':
      context=`想把兩個名詞連成「${descriptor.label}」這個詞組。`;
      sentence=`${a.jp}＿${b.jp}です。`;translation=`是${descriptor.label}。`;
      why=`「${plain(a.jp)}」透過「の」說明「${plain(b.jp)}」的類別；這裡不只是物品所有權。`;words=[a,b];break;
    case 'also-person':
      context=`剛得知小林是${b.zh}。你要接著說「${a.zh}也是${b.zh}」，明確表達相同身分。`;
      sentence=`${a.jp}＿${b.jp}です。`;translation=`${a.zh}也是${b.zh}。`;
      why=`前面已有「小林是${b.zh}」的資訊，「${plain(a.jp)}も」把相同身分加到${a.zh}身上。`;words=[a,b];break;
    case 'also-thing':
      context=`朋友剛指出一個${b.zh}。你指著另一個物品，補充說「${a.zh}也是${b.zh}」。`;
      sentence=`${a.jp}＿${b.jp}です。`;translation=`${a.zh}也是${b.zh}。`;
      why=`用「${plain(a.jp)}も」指出另一個東西也有相同的類別。`;words=[a,b];break;
    case 'person-place':
      context=`回答人物在哪裡，說「${a.zh}在${b.zh}」。這裡只說明位置。`;
      sentence=`${a.jp}は${b.jp}＿います。`;translation=`${a.zh}在${b.zh}。`;
      why=`「います」表示人存在於某處，位置「${plain(b.jp)}」後面用「に」。`;words=[a,b,word('iru','います','在；存在（人或動物）')];break;
    case 'thing-place':
      context=`描述物品的位置：${a.zh}有${b.zh}。`;
      sentence=`${a.jp}＿${b.jp}があります。`;translation=`${a.zh}有${b.zh}。`;
      why=`這裡的「あります」描述${b.zh}的存在，存在位置用「に」。`;words=[a,b,word('aru','あります','有；存在（物品）')];break;
    case 'travel':{
      const verb=c;
      context=verb.id==='come'?`你在${b.zh}等人。說「${a.zh}會來${b.zh}」。選一個自然的說法即可。`:`說明${a.zh}接下來的行程：「${a.zh}要去${b.zh}」。選一個自然的說法即可。`;
      sentence=`${a.jp}は${b.jp}＿${verb.jp}。`;translation=`${a.zh}要${verb.zh}${b.zh}。`;
      why=`在這個一般移動情境，「${plain(b.jp)}に${plain(verb.jp)}」與「${plain(b.jp)}へ${plain(verb.jp)}」都成立。`;
      words=[a,b,verb];break;
    }
    case 'return':
      context=`活動結束，說「${a.zh}要回家」。選一個自然的說法即可。`;
      sentence=`${a.jp}はうち＿{帰|かえ}ります。`;translation=`${a.zh}要回家。`;
      why='「うちに帰ります」與「うちへ帰ります」都能表達回家，兩個答案都接受。';words=[a,word('home','うち','家'),word('return','{帰|かえ}ります','回去')];break;
    default:throw Error('Unknown particle template');
  }
  const rules=optionRules[use];
  return {id,lesson,use,context,sentence,translation,why,words,options:[...rules.options],answers:[...rules.answers],wrong:{...rules.wrong},generated:true};
}
const descriptors=[];
function add(family,lesson,use,slots,extra={}){
  descriptors.push({id:`v1:${family}:${slots.map(s=>s.id).join(':')}${extra.verb?':'+extra.verb.id:''}`,family,lesson,use,slots,...extra});
}
for(const p of people)for(const r of roles){add('identity','wa','topic',[p,r]);add('also-person','mo','addition',[p,r]);}
for(const p of pointers)for(const t of things){add('identify','wa','topic',[p,t]);add('also-thing','mo','addition',[p,t]);}
for(const g of groups)for(const p of g.places)for(const obj of g.objects){add('object','wo','object',[p,obj],{verb:g.verb});add('action','ni-de','action',[p,obj],{verb:g.verb});}
for(const p of people)for(const t of things)add('owner','no','possession',[p,t]);
for(const [a,b,label] of categories)add('category','no','category',[a,b],{label});
for(const p of people)for(const place of places)add('person-place','ni-de','existence',[p,place]);
for(const spot of spots)for(const t of smallThings)add('thing-place','ni-de','existence',[spot,t]);
// 「来ます」 assumes the speaker is at the destination; use other people, not self.
for(const p of people.slice(1))for(const dest of destinations)for(const verb of travelVerbs)add('travel','ni-he','movement',[p,dest,verb]);
for(const p of people)add('return','ni-he','movement',[p]);

const fixed=new Set(allParticleQuestions.map(q=>`${q.lesson}:${signature(q)}`));
// Filter exact sentences already used by that lesson's fixed assessment.
const catalog=descriptors.filter(d=>!fixed.has(`${d.lesson}:${signature(buildQuestion(d))}`));
const byId=new Map(catalog.map(d=>[d.id,d]));
export const variationCounts=Object.fromEntries(particleLessons.map(l=>[l.id,catalog.filter(d=>d.lesson===l.id).length]));
export const variationTotal=catalog.length;
export const RECENT_LIMIT=120;
export function cleanVariationRecent(raw){
  if(!Array.isArray(raw))return [];
  return [...new Set(raw.filter(id=>typeof id==='string'&&byId.has(id)).reverse())].reverse().slice(-RECENT_LIMIT);
}
export function noteVariationShown(progress,question){
  if(!question.generated||!byId.has(question.id))return;
  progress.recentVariations=cleanVariationRecent([...(progress.recentVariations||[]),question.id]);
}
export function questionFromVariationId(id){const d=byId.get(id);return d?buildQuestion(d):null;}
export const variationIds=()=>catalog.map(d=>d.id);
function shuffle(items,rng){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function ranked(pool,recent,rng){
  const ranks=new Map(recent.map((id,i)=>[id,i]));
  return shuffle(pool,rng).sort((a,b)=>(ranks.get(a.id)??-1)-(ranks.get(b.id)??-1));
}
export function variationQueue(scope='all',recent=[],rng=Math.random){
  if(scope!=='all'&&!particleLessons.some(l=>l.id===scope))return [];
  const history=cleanVariationRecent(recent),selected=[],seen=new Set();
  const choose=pool=>{
    const d=ranked(pool.filter(d=>!selected.some(s=>s.id===d.id)),history,rng).find(d=>!seen.has(signature(buildQuestion(d))));
    if(d){selected.push(d);seen.add(signature(buildQuestion(d)));}return d;
  };
  if(scope==='all')for(const l of shuffle(particleLessons,rng))choose(catalog.filter(d=>d.lesson===l.id));
  else{
    const pool=catalog.filter(d=>d.lesson===scope),uses=[...new Set(pool.map(d=>d.use))];
    // Six questions balanced across the lesson's usages (e.g. existence/action: three each).
    for(let i=0;i<6;i++)choose(pool.filter(d=>d.use===uses[i%uses.length]));
  }
  return shuffle(selected,rng).map(buildQuestion);
}
export function reviewVariation(use,recent=[],rng=Math.random){
  const d=ranked(catalog.filter(d=>d.use===use),cleanVariationRecent(recent),rng)[0];
  return d?buildQuestion(d):null;
}
